func TestParseSessionParentMissing(t *testing.T) {
	dir := t.TempDir()
	_, err := ParseSession(SessionFiles{ID: "x", Parent: filepath.Join(dir, "x.jsonl")})
	if err == nil {
		t.Fatal("want an error when the parent transcript cannot be opened")
