package agentusage

import (
	"os"
	"path/filepath"
)

// ParseSession aggregates the usage of every agent of a session. It fails
// only if the parent transcript cannot be opened; a sub-agent that cannot be
// read stays in Agents with no tokens and a FileIssue.
func ParseSession(files SessionFiles) (Usage, error) {
	agents := []Agent{{Main: true, State: StateUnknown}}
	for _, sa := range files.SubAgents {
		agents = append(agents, Agent{ID: sa.ID})
	}
	agg := newAggregator(agents)
	// Sub-agents are folded in ID order, whatever order the caller used.
	order := sortedSubAgents(files.SubAgents)
	if err := parseFile(agg, 0, files.Parent); err != nil {
		return Usage{}, baseOnly(err)
	}
	for i, sa := range order {
		idx := i + 1
		agg.agents[idx] = agentFromMeta(agg, sa)
		if err := parseFile(agg, idx, sa.Transcript); err != nil {
			agg.diag.Files = append(agg.diag.Files, FileIssue{File: filepath.Base(sa.Transcript), Kind: IssueOpenFailed})
		}
	}
	return Usage{
		SessionID:   files.ID,
		Agents:      agg.finish(),
		Versions:    agg.versions(),
		Diagnostics: agg.diag,
	}, nil
}

// agentFromMeta builds a sub-agent's identity from its meta file, counting
// a missing or unreadable one.
func agentFromMeta(agg *aggregator, sa SubAgentFiles) Agent {
	ag := Agent{ID: sa.ID}
	if sa.Meta == "" {
		agg.diag.MetaMissing++
		return ag
	}
	m, err := readMeta(sa.Meta)
	if err != nil {
		agg.diag.MetaUnreadable++
		return ag
	}
	ag.Type, ag.State, ag.SpawnDepth = m.AgentType, m.state(), m.SpawnDepth
	return ag
}

// sortedSubAgents returns the sub-agents ordered by ID without touching the
// caller's slice.
func sortedSubAgents(in []SubAgentFiles) []SubAgentFiles {
	out := append([]SubAgentFiles(nil), in...)
	sortByID(out)
	return out
}

// parseFile reads one transcript into the aggregator for agent idx. It
// fails only if the file cannot be opened.
func parseFile(agg *aggregator, idx int, path string) error {
	f, err := openPlain(path, false)
	if err != nil {
		return err
	}
	if f == nil {
		return errNotPlain
	}
	defer func() { _ = f.Close() }()
	name := filepath.Base(path)
	before := agg.diag
	res, err := scanLines(f, MaxLineBytes, func(line []byte, off int64) {
		agg.addLineIssue(idx, name, off, line)
	})
	if err != nil {
		agg.diag.UnreadableLines++ // read error mid-file: what was read still counts
		agg.diag.Files = append(agg.diag.Files, FileIssue{File: name, Offset: res.Consumed, Kind: IssueUnreadable})
	}
	for range res.Oversized {
		agg.diag.OversizedLines++
	}
	_ = before
	if len(res.Tail) > 0 {
		agg.diag.TruncatedFiles = append(agg.diag.TruncatedFiles, name)
	}
	return nil
}

var _ = os.ErrNotExist
EOF

